const $=s=>document.querySelector(s);
const paths={grid:'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/>',shield:'<path d="M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6Z"/><path d="m8 12 3 3 5-6"/>',chart:'<path d="M4 3v17h17M8 15v-4m5 4V6m5 9v-6"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',droplet:'<path d="M12 3C10 6 5 11 5 15a7 7 0 0 0 14 0c0-4-5-9-7-12Z"/><path d="M8 15a4 4 0 0 0 4 4"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',chevron:'<path d="m9 5 7 7-7 7"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',message:'<path d="M21 11a8 8 0 0 1-8 8H7l-4 3V7a4 4 0 0 1 4-4h10a4 4 0 0 1 4 4Z"/><path d="M7 8h10M7 12h6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',layers:'<path d="m12 3 10 5-10 5L2 8Zm-10 9 10 5 10-5M2 17l10 5 10-5"/>',sparkles:'<path d="m12 3 2.6 6.4L21 12l-6.4 2.6L12 21l-2.6-6.4L3 12l6.4-2.6ZM20 2v4m-2-2h4"/>',check:'<path d="m5 12 4 4L19 6"/>',reset:'<path d="M4 9a8 8 0 1 1 0 6M4 3v6h6"/>'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${paths[n]||paths.grid}</svg>`;
function hydrate(){document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon))}
const events=[
{id:1,title:'行驶中异常断电反馈',source:'企微社群',topic:'车辆安全',level:'high',time:'09:42',count:6,status:'pending',text:'今天通勤时车突然断电，停下重新开机后恢复了，想问一下应该先检查哪里？',reason:'描述了行驶中的异常现象，建议优先核实车辆状态与发生经过。该表述不足以确认故障原因。',gap:'车型、发生时间、速度、仪表提示及售后检测结果均待补充。'},
{id:2,title:'充电过程反复中断',source:'抖音评论',topic:'充电体验',level:'medium',time:'09:26',count:12,status:'pending',text:'最近充电总是断断续续，换了插座还是这样，有人遇到过吗？',reason:'识别到充电体验问题。此内容为独立评论，无上下文；不能据此判定电池或充电器故障。',gap:'充电器规格、插座环境、故障提示及复现情况均待核实。'},
{id:3,title:'维修进度沟通不及时',source:'小红书',topic:'售后服务',level:'medium',time:'09:18',count:9,status:'pending',text:'车送修几天了，还没有明确进度，希望门店能告知预计完成时间。',reason:'用户诉求集中在维修时效与信息沟通，应先确认服务记录与承诺时间。',gap:'门店、送修日期、服务记录及双方沟通情况待核实。'},
{id:4,title:'通勤续航变化讨论',source:'民间微信群',topic:'续航体验',level:'low',time:'08:55',count:18,status:'pending',text:'最近感觉同样路线耗电快了些，有没有类似使用情况？',reason:'存在续航体验线索，但缺少温度、载重与驾驶习惯等信息，建议持续观察。',gap:'车型、气温、里程、载重及骑行模式待补充，不推断电池质量问题。'}];
const data={today:{label:'今日',total:'12,864',topics:18,delta:'12.8%',x:['00:00','04:00','08:00','12:00','16:00','20:00','24:00'],a:[23,25,20,28,37,30,46,42,52,67,58,63,55,70,79,65,72,83,78,91,83,96,89,93],b:[12,15,13,18,22,20,26,21,29,32,28,35,31,38,43,37,40,45,41,49,45,52,48,51],shares:[58,22,12,8]},week:{label:'近7天',total:'89,732',topics:43,delta:'8.6%',x:['09.09','09.10','09.11','09.12','09.13','09.14','09.15'],a:[35,42,37,50,45,49,68,60,74,66,77,80,72,79],b:[19,23,20,28,23,27,37,34,41,38,44,49,41,46],shares:[54,24,14,8]},month:{label:'近30天',total:'386,420',topics:126,delta:'16.2%',x:['08.17','08.22','08.27','09.01','09.06','09.11','09.15'],a:[29,40,32,47,39,53,71,48,53,42,49,67,58,75,81,67,79,89,82,97],b:[14,17,20,18,25,31,37,26,32,24,29,37,30,41,43,38,47,49,44,56],shares:[56,20,15,9]}};
let period='today',filter='all',source='all',view='overview',toastTimer,lastFocus;
const pending=()=>events.filter(e=>e.status==='pending');
const statusLabel=e=>e.status==='confirmed'?'已核验':e.status==='observe'?'持续观察':e.level==='high'?'优先核验':e.level==='low'?'持续观察':'待核验';
function periods(){return `<div class="period" role="group" aria-label="选择统计时间">${Object.entries(data).map(([k,d])=>`<button data-period="${k}" class="${period===k?'active':''}" aria-pressed="${period===k}">${d.label}</button>`).join('')}</div>`}
function metric(label,value,note,ico,unit=''){return `<article class="card metric"><div class="metric-label">${label}</div><div class="metric-value">${value}<small>${unit}</small></div><div class="metric-note">${note}</div><span class="metric-icon">${icon(ico)}</span></article>`}
function chart(){const d=data[period],points=arr=>arr.map((v,i)=>[35+i*505/(arr.length-1),140-v*(115/120)]);const path=arr=>points(arr).map(([x,y],i)=>`${i?'L':'M'}${x.toFixed(1)} ${y.toFixed(1)}`).join(' ');const a=path(d.a),b=path(d.b);return `<svg class="chart" viewBox="0 0 565 175" role="img" aria-label="${d.label}虚构线索趋势，社群与公域分别展示"><defs><linearGradient id="area-blue" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#8bb6ff" stop-opacity=".25"/><stop offset="1" stop-color="#8bb6ff" stop-opacity="0"/></linearGradient><linearGradient id="area-purple" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#b6a8ed" stop-opacity=".18"/><stop offset="1" stop-color="#b6a8ed" stop-opacity="0"/></linearGradient></defs><g stroke="#a9bed4" stroke-opacity=".16" stroke-dasharray="3 4"><path d="M35 25H540M35 63H540M35 102H540M35 140H540"/></g><g><text x="3" y="29">120</text><text x="8" y="67">80</text><text x="8" y="106">40</text><text x="14" y="144">0</text></g><path d="${a} L540 140 L35 140 Z" fill="url(#area-blue)"/><path d="${b} L540 140 L35 140 Z" fill="url(#area-purple)"/><path d="${a}" fill="none" stroke="#76a3f5" stroke-width="2" stroke-linejoin="round"/><path d="${b}" fill="none" stroke="#b2a3e7" stroke-width="1.8" stroke-linejoin="round"/>${points(d.a).filter((_,i)=>i%4===0).map(([x,y])=>`<circle cx="${x}" cy="${y}" r="2.4" fill="#7c9fea" stroke="#fff" stroke-width="1"/>`).join('')}${d.x.map((v,i)=>`<text x="${35+i*505/6}" y="165" text-anchor="${i===0?'start':i===6?'end':'middle'}">${v}</text>`).join('')}</svg>`}
function channels(){return `<article class="card"><div class="card-head"><h2>声音来自哪里</h2><small>${data[period].label} · 示例占比</small></div><div class="channels">${[['企','企微社群'],['微','民间微信群'],['红','小红书'],['抖','抖音评论']].map(([logo,name],i)=>`<div class="channel-row"><div class="channel-logo">${logo}</div><span>${name}</span><div class="bar"><i style="width:${data[period].shares[i]}%"></i></div><small>${data[period].shares[i]}%</small></div>`).join('')}</div><div class="channel-foot">社群与公域独立采样 · 数值仅用于展示布局</div></article>`}
function rows(list){return list.length?list.map(e=>`<button class="event-row" data-event="${e.id}"><span class="event-dot ${e.level}"></span><span class="event-main"><b>${e.title}</b><small>${e.source} · ${e.time} · ${e.topic}</small></span><span class="badge ${e.status!=='pending'?'done':e.level}">${statusLabel(e)}</span>${icon('chevron')}</button>`).join(''):'<div class="empty">没有匹配的事件<br><small>试试其他关键词或筛选条件</small></div>'}
function filtered(){const q=$('#search').value.trim().toLowerCase();return events.filter(e=>(!q||[e.title,e.topic,e.source,e.text].some(t=>t.toLowerCase().includes(q)))&&(source==='all'||source===e.source)&&(filter==='all'||filter==='pending'&&e.status==='pending'||filter==='high'&&e.level==='high'&&e.status==='pending'||filter==='done'&&e.status!=='pending'))}
function chips(full=false){return `<div class="table-tools" role="group" aria-label="筛选事件状态">${(full?[['all','全部事件'],['pending','待核验'],['high','优先核验'],['done','已处理']]:[['all','全部'],['high','优先核验']]).map(([k,t])=>`<button class="chip ${filter===k?'active':''}" data-filter="${k}" aria-pressed="${filter===k}">${t}</button>`).join('')}</div>`}
function overview(){const d=data[period];return `<section class="hero"><div class="hero-copy"><div class="eyebrow">THE VOICE BEHIND EVERY RIDE</div><h1>听见每一程，<br><span>洞察每一种声音。</span></h1><p>从分散的用户反馈，到清晰、可行动的洞察。</p><div class="hero-bottom"><a class="button primary" href="#review">进入风险核验 ${icon('arrow')}</a><span class="hero-time">2026 年 9 月 15 日 · 星期二</span></div></div><div class="hero-art" aria-hidden="true"><div class="orb"></div><div class="orbit"></div><div class="floating-tag">✧ &nbsp; CONNECTING VOICES</div><div class="floating-card"><small>值得关注的声音</small><b>${d.topics}</b><span>个话题</span></div><div class="art-caption">A LITTLE CLARITY. EVERY DAY.</div></div></section><div class="section-heading"><h2>舆情脉搏 <small>每一个变化，都有迹可循</small></h2>${periods()}</div><section class="metrics">${metric('分析消息',d.total,`<span class="up">↗ ${d.delta}</span>较上一周期 · 示例`,'message')}${metric('关注话题',d.topics,'<span class="up">4 个</span>重点主题待观察','layers','个')}${metric('待核验事件',pending().length,`<span class="down">${pending().filter(e=>e.level==='high').length} 项优先</span>等待人工核实`,'shield','项')}${metric('已核验事件',events.filter(e=>e.status==='confirmed').length,'<span class="up">本次演示</span>核验后即时更新','check','项')}</section><section class="middle-grid"><article class="card"><div class="card-head"><h2>线索趋势</h2><div class="legend"><span><i></i>社群</span><span><i></i>公域</span></div></div><div class="trend-stat">${d.label}线索变化 <b>↗ ${d.delta}</b></div>${chart()}<div class="chart-foot"><span>单位：条 · 虚构示意</span><span>渠道口径不同，不直接比较负面率</span></div></article>${channels()}</section><section class="bottom-grid"><article class="card"><div class="card-head"><h2>需要关注的事件</h2>${chips()}</div><div class="event-list" id="event-list">${rows(filtered())}</div></article><article class="card quote-card"><div class="insight-label">${icon('sparkles')} INSIGHT OF THE DAY</div><h3>把分散的反馈，<br>连成<span>更清晰的理解。</span></h3><p>充电体验与售后沟通是本次示例的观察主题。相似的表达，仍需要逐条核实。</p><a class="text-button" href="#insights">探索问题洞察 &nbsp; ↗</a><div class="quote-orb" aria-hidden="true"></div></article></section>`}
function review(){return `<div class="page-title"><div><div class="eyebrow">EVIDENCE BEFORE CONCLUSIONS</div><h1>风险核验</h1><p>先还原用户的表达，再做有依据的判断。</p></div><button class="button" id="reset">${icon('reset')}重置演示</button></div><div class="review-summary">${metric('待人工核验',pending().length,'逐条检查信息与证据','clock','项')}${metric('优先核验',pending().filter(e=>e.level==='high').length,'涉及车辆安全的表述','shield','项')}${metric('已处理',events.filter(e=>e.status!=='pending').length,'本次演示操作记录','check','项')}</div><article class="card review-card"><div class="card-head"><h2>事件队列</h2><small>2026.09.15 · 虚构案例</small></div><div class="filter-row">${chips(true)}<select id="source" aria-label="筛选来源"><option value="all">全部来源</option>${events.map(e=>`<option ${source===e.source?'selected':''}>${e.source}</option>`).join('')}</select></div><div id="event-list">${rows(filtered())}</div></article><article class="card flow-card"><div class="card-head"><h2>每一步，让判断更有依据</h2><small>核验流程</small></div><div class="flow"><span>01 · 线索发现</span><b>→</b><span>02 · 证据核实</span><b>→</b><span>03 · 人工判断</span><b>→</b><span>04 · 结论回流</span></div></article>`}
function insights(){return `<div class="page-title"><div><div class="eyebrow">SMALL SIGNALS. BIGGER PICTURE.</div><h1>问题洞察</h1><p>围绕真实诉求组织线索，让下一步更清晰。</p></div><span class="demo-pill">4 个示例主题</span></div><div class="insight-grid">${events.map((e,i)=>`<article class="card topic-card"><div class="topic-top"><span>ISSUE / 0${i+1}</span>${icon(['shield','droplet','message','chart'][i])}</div><h2>${e.topic}</h2><p>${e.reason}</p><div class="topic-data"><div><b>${e.count}</b><span>示例线索</span></div><div><b>${[2,3,2,3][i]}</b><span>示例渠道</span></div></div><div class="topic-bottom"><span class="badge ${e.level}">同类问题线索</span><button class="text-button" data-event="${e.id}">查看代表案例 &nbsp; ↗</button></div></article>`).join('')}</div><article class="card flow-card"><div class="insight-label">${icon('sparkles')} 观察提示</div><p style="color:#8899b2;font-size:11px">相似表达只作为主题线索，不代表已确认故障、同一事件或跨渠道传播。独立评论保持独立，不补造上下文。</p></article>`}
function render(){view=['overview','review','insights'].includes(location.hash.slice(1))?location.hash.slice(1):'overview';$('#breadcrumb').textContent={overview:'态势总览',review:'风险核验',insights:'问题洞察'}[view];document.querySelectorAll('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===view);if(a.dataset.nav===view)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});$('#nav-count').textContent=pending().length;$('#main').innerHTML=view==='review'?review():view==='insights'?insights():overview();$('#main').classList.remove('fade-in');void $('#main').offsetWidth;$('#main').classList.add('fade-in');hydrate()}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3200)}
function showDialog(html){if(!$('#detail').open)lastFocus=document.activeElement;$('#detail-content').innerHTML=html;hydrate();if(!$('#detail').open)$('#detail').showModal()}
function openEvent(id){const e=events.find(e=>e.id===id);showDialog(`<div class="detail-eyebrow">VOICE / 00${e.id} · 虚构案例</div><h2 id="detail-title">${e.title}</h2><div class="detail-meta"><span>${e.source} · ${e.time}</span><span class="badge ${e.status!=='pending'?'done':e.level}">${statusLabel(e)}</span></div><h3>用户原文 · 虚构示例</h3><blockquote>“${e.text}”</blockquote><h3>核验参考</h3><p>${e.reason}</p><h3>还需要了解</h3><p>${e.gap}</p><div class="detail-note">此处为设计演示文案，并非模型实际分析结果。操作仅改变本页状态，刷新后重置。</div><div class="dialog-actions"><button class="button primary" data-confirm="${id}" ${e.status==='confirmed'?'disabled':''}>${icon('check')}${e.status==='confirmed'?'已完成核验':'模拟完成核验'}</button><button class="button" data-observe="${id}" ${e.status==='observe'?'disabled':''}>${e.status==='observe'?'已加入观察':'继续观察'}</button></div>`)}
function closeDialog(){$('#detail').close();if(lastFocus?.isConnected)lastFocus.focus()}
$('#detail').addEventListener('click',e=>{if(e.target===$('#detail')){const r=$('#detail').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog()}});
$('.close-dialog').onclick=closeDialog;
document.addEventListener('click',e=>{const t=e.target.closest('button');if(!t)return;if(t.dataset.period){period=t.dataset.period;render()}if(t.dataset.filter){filter=t.dataset.filter;render()}if(t.dataset.event)openEvent(Number(t.dataset.event));if(t.dataset.confirm||t.dataset.observe){const id=Number(t.dataset.confirm||t.dataset.observe);events.find(x=>x.id===id).status=t.dataset.confirm?'confirmed':'observe';render();openEvent(id);toast(t.dataset.confirm?'已记录模拟核验结果':'已加入持续观察')}if(t.id==='reset'){events.forEach(e=>e.status='pending');filter='all';source='all';$('#search').value='';render();toast('演示状态已重置')}});
document.addEventListener('change',e=>{if(e.target.id==='source'){source=e.target.value;$('#event-list').innerHTML=rows(filtered())}});
$('#search').addEventListener('input',()=>{filter='all';source='all';if(view!=='review'){location.hash='review'}else render()});
$('#glass-level').addEventListener('input',e=>document.documentElement.style.setProperty('--glass-alpha',e.target.value/100));
$('#notifications').onclick=()=>showDialog(`<div class="detail-eyebrow">WORKSPACE / NOTIFICATIONS</div><h2 id="detail-title">工作提醒</h2><div class="notification-item"><b>${pending().filter(e=>e.level==='high').length} 项安全相关表述等待优先核验</b><p>先确认发生场景，再补齐车辆与服务信息。</p></div><div class="notification-item"><b>${events.filter(e=>e.status==='observe').length} 项事件正在持续观察</b><p>关注后续反馈，保留尚未确认的信息。</p></div><div class="notification-item"><b>当前为本地设计演示</b><p>提醒为虚构示例，所有核验操作仅保存在本页内存中。</p></div><div class="dialog-actions"><button class="button primary" id="go-review">查看核验队列 ${icon('arrow')}</button></div>`);
document.addEventListener('click',e=>{if(e.target.closest('#go-review')){closeDialog();filter='all';source='all';$('#search').value='';if(location.hash==='#review')render();else location.hash='review'}});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if(!$('#detail').open)$('#search').focus()}});
window.addEventListener('hashchange',()=>{filter='all';source='all';render();window.scrollTo({top:0,behavior:'instant'})});
hydrate();render();
